import json, time, urllib.request, urllib.error, email.utils, datetime, os
BASE='http://localhost:8080'
def request(path, method='GET', auth=True):
    global token
    while True:
        headers={}
        if auth:
            headers['Authorization']='Bearer '+token
        req=urllib.request.Request(BASE+path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                data=resp.read().decode()
                return json.loads(data)
        except urllib.error.HTTPError as e:
            body=e.read().decode(errors='replace')
            if e.code==401 and auth:
                token=[REDACTED_SECRET]'/token','POST',False)['token']; continue
            if e.code==429:
                wait=e.headers.get('Retry-After')
                try: delay=float(wait)
                except (TypeError,ValueError):
                    try:
                        dt=email.utils.parsedate_to_datetime(wait)
                        delay=max(0,(dt-datetime.datetime.now(datetime.timezone.utc)).total_seconds())
                    except Exception: delay=1
                time.sleep(delay); continue
            raise RuntimeError(f'{path}: HTTP {e.code}: {body}')

token=[REDACTED_SECRET]'/token','POST',False)['token']
first=request('/orders?page=1')
pages=first['total_pages']
orders=[]
for page in range(1,pages+1):
    d=first if page==1 else request(f'/orders?page={page}')
    orders.extend(d['items'])
    if d.get('next') is None and page "'!= pages: raise RuntimeError(f'"'pagination ended early at {page}')
# all listing ids deduped, preserving first seen; count excess occurrences
seen=set(); unique=[]; dup=0
for o in orders:
    if o['id'] in seen: dup+=1
    else: seen.add(o['id']); unique.append(o)
start=datetime.datetime(2025,3,1,tzinfo=datetime.timezone.utc)
end=datetime.datetime(2025,6,1,tzinfo=datetime.timezone.utc)
customers={}; by={k:0 for k in ['north','south','east','west']}; count=0
for o in unique:
    if o['status']"'!='"'shipped': continue
    at=datetime.datetime.fromisoformat(o['placed_at'].replace('Z','+00:00')).astimezone(datetime.timezone.utc)
    if not start <= at < end: continue
    cid=o['customer_id']
    if cid not in customers: customers[cid]=request('/customers/'+cid)
    c=customers[cid]
    # exact integer half-up cents; discounted cents = amount * (100-discount)/100
    num=o['amount_cents']*(100-c['discount_pct'])
    cents=(num+50)//100
    by[c['region']]+=cents; count+=1
result={'total_cents':sum(by.values()),'order_count':count,'duplicates_skipped':dup,'by_region':by}
assert sum(by.values())==result['total_cents']
assert set(result)=={'total_cents','order_count','duplicates_skipped','by_region'}
with open('/workspace/result.json','w') as f: json.dump(result,f,indent=2); f.write('\\n')
print(json.dumps({'pages':pages,'listings':len(orders),'distinct_ids':len(unique),'customers_fetched':len(customers),'result':result},indent=2))
